import React, { useState, useMemo } from 'react';

// ─── Channel meta (WEB-FIRST) ────────────────────────────────────────────────
const CHANNEL_META = {
  'Web Push':  { color: '#f59e0b', bg: 'rgba(245,158,11,0.10)', border: 'rgba(245,158,11,0.25)', icon: '🔔' },
  'Email':     { color: '#3b82f6', bg: 'rgba(59,130,246,0.10)', border: 'rgba(59,130,246,0.25)', icon: '✉️' },
  'SMS':       { color: '#22c55e', bg: 'rgba(34,197,94,0.10)',  border: 'rgba(34,197,94,0.25)',  icon: '💬' },
  'WhatsApp':  { color: '#25D366', bg: 'rgba(37,211,102,0.10)', border: 'rgba(37,211,102,0.25)', icon: '🟢' },
  'On-site':   { color: '#a78bfa', bg: 'rgba(167,139,250,0.10)',border: 'rgba(167,139,250,0.25)',icon: '🌐' },
};

// ─── Allowed channels for WEB use-case ───────────────────────────────────────
const WEB_CHANNELS = ['Web Push', 'Email', 'SMS', 'WhatsApp', 'On-site'];

// ─── Helper: Filter only supported channels ──────────────────────────────────
function adaptCampaignToWeb(campaign) {
  return {
    ...campaign,
    channels: campaign.channels.filter(c => WEB_CHANNELS.includes(c)),
    steps: campaign.steps.filter(s => WEB_CHANNELS.includes(s.channel)),
  };
}

