// ─── Campaign selector ───────────────────────────────────────────────────────
function selectCampaigns(events) {
  const names = events.map(e => e.eventName.toLowerCase());

  return CAMPAIGN_TEMPLATES
    .map(t => ({
      ...t,
      score: t.match.reduce((a, k) => a + (names.some(n => n.includes(k)) ? 1 : 0), 0)
    }))
    .filter(t => t.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 5);
}

// ─── Channel pill ────────────────────────────────────────────────────────────
function ChannelPill({ channel }) {
  const m = CHANNEL_META[channel];
  return (
    <span style={{
      padding: '3px 10px',
      borderRadius: 999,
      fontSize: 11,
      fontWeight: 700,
      background: m.bg,
      border: `1px solid ${m.border}`,
      color: m.color,
    }}>
      {m.icon} {channel}
    </span>
  );
}

// ─── Step Row ────────────────────────────────────────────────────────────────
function StepRow({ step }) {
  return (
    <div style={{ padding: '10px 0', borderBottom: '1px solid var(--border)' }}>
      <div style={{ display: 'flex', gap: 10 }}>
        <span>⏱ {step.delay}</span>
        <ChannelPill channel={step.channel} />
      </div>
      <p style={{ margin: 0 }}>{step.message}</p>
    </div>
  );
}

// ─── Campaign Card ───────────────────────────────────────────────────────────
function CampaignCard({ campaign }) {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ border: '1px solid var(--border)', marginBottom: 10 }}>
      <div onClick={() => setOpen(!open)} style={{ cursor: 'pointer', padding: 12 }}>
        <strong>{campaign.name}</strong>
      </div>

      {open && (
        <div style={{ padding: 12 }}>
          <p>{campaign.goal}</p>

          {campaign.steps.map((s, i) => (
            <StepRow key={i} step={s} />
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Main Component ──────────────────────────────────────────────────────────
export default function CampaignSuggestions({ result, selected }) {

  const campaigns = useMemo(() => {
    if (!result?.recommendedEvents) return [];

    const events = result.recommendedEvents.filter(e =>
      selected?.size ? selected.has(e.eventName) : true
    );

    return selectCampaigns(events);
  }, [result, selected]);

  if (!campaigns.length) return null;

  return (
    <div style={{ marginTop: 20 }}>
      <h3>🎯 Web Campaign Playbook</h3>

      {campaigns.map((c, i) => (
        <CampaignCard key={i} campaign={c.campaign} />
      ))}
    </div>
  );
}
